<?php $providers=$a->oauth->available();if($providers): ?><div class="social-divider"><span><?= t('Or use a connected account') ?></span></div><div class="provider-actions"><?php foreach($providers as $key=>$label): ?><?= form_start('oauth_begin').hidden('provider',$key).hidden('purpose','login') ?><button class="btn secondary full" type="submit"><span class="provider-mark" aria-hidden="true"><?= e(substr($label,0,1)) ?></span><?= e($label) ?><?= icon('arrow') ?></button></form><?php endforeach ?></div><p class="hint"><?= t('External identities are linked explicitly, never merged by email address.') ?></p><?php endif ?>
